from lib import *
S = SS('h25')
steps = [
    step("最基本的 TLS:服务端证书由 demo-root-ca 签发(SAN 里有 svc.demo.test),客户端信任这个 CA、ServerName 设为 svc.demo.test:调用成功。服务端从连接里看到:TLS 版本 TLS 1.3,密码套件 TLS_AES_128_GCM_SHA256,ALPN 协商结果 “h2”(gRPC 要求 HTTP/2,TLS 里靠 ALPN 声明),客户端证书数 0(普通 TLS 里服务端不要求客户端证书)。证书是我用 Go 的 crypto/x509 在内存里生成的,没有落盘。", t=tl(S(1)), done=lidx(S(1), '服务端看到'), mark=lidx(S(1), '调用:成功'), b=bars([['客户端证书数', 0, '0'], ['协商的 HTTP 协议', 2, 'h2']], 3, mark=[0], done=[1]), kv=KV([['TLS 版本', 'TLS 1.3'], ['密码套件', 'TLS_AES_128_GCM_SHA256'], ['ALPN', 'h2']], ['ALPN'])),
    step("服务端证书有问题时客户端看到的错误,全都是 code=Unavailable,原因在 message 里,而且是 fail-fast 立即返回(0.5~1.5 ms,系统验证器那条 15.6 ms)。客户端不信任签发者:“x509: certificate signed by unknown authority”;域名对不上:“x509: certificate is valid for svc.demo.test, not wrong.example”;证书已过期:“x509: certificate has expired or is not yet valid: current time … is after …”;证书只有 CN、没有 SAN:“x509: certificate relies on legacy Common Name field, use SANs instead”;客户端没配根证书用系统根(这台是 macOS 的验证器):“x509: “server” certificate is not trusted”;服务端是明文、客户端用 TLS:“tls: first record does not look like a TLS handshake”;服务端最高 TLS 1.2、客户端要求至少 1.3:“remote error: tls: protocol version not supported”;服务端 TLS、客户端用明文:“error reading server preface: EOF”。前七条前面都带“transport: authentication handshake failed”。", t=tl(S(2)), done=lidx(S(2), '服务端 TLS,客户端用明文'), mark=lidx(S(2), '客户端不信任签发者'), b=bars([['出错场景数(全部 Unavailable)', 8, '8']], 9, done=[0]), kv=KV([['证书类问题', 'x509: …(未知签发者 / 域名 / 过期 / 无 SAN)'], ['协议类问题', 'first record does not look like TLS / protocol version not supported'], ['明文客户端连 TLS 服务端', 'error reading server preface: EOF']], ['证书类问题'])),
    step("mTLS(服务端 RequireAndVerifyClientCert):客户端没有证书,调用失败 Unavailable,“error reading server preface: remote error: tls: certificate required”(1.7 ms);客户端有 other-ca 签发的证书但按正常方式配置:错误和没有证书一模一样(我的推断:Go 的 TLS 客户端大概只会发送签发者在服务端 CA 列表里的证书,否则就当没有——下一句“强制发送”的结果与这个推断相符);用 GetClientCertificate 强制发送这张证书:“remote error: tls: unknown certificate authority”;客户端证书由 demo-root-ca 签发:成功,服务端 handler 从 peer 的 AuthInfo 读到证书 CN=“client-A”——这就是 mTLS 里“用证书确定调用者身份”的做法。注意:TLS 1.3 下客户端握手先完成,服务端的拒绝在“读服务端前言”时才报出来,所以错误前缀是“error reading server preface”,不是“authentication handshake failed”。", t=tl(S(3)), done=lidx(S(3), '客户端证书由 demo-root-ca 签发'), mark=lidx(S(3), '客户端没有证书'), b=bars([['被拒绝的情形(没有证书 / 正常配置的错 CA / 强制发送错 CA)', 3, '3'], ['合法证书', 1, '1']], 4, mark=[0], done=[1]), kv=KV([['没有证书', 'certificate required'], ['错误 CA 强制发送', 'unknown certificate authority'], ['合法证书', '成功,服务端读到 CN=client-A']], ['合法证书'])),
    step("证书轮换:服务端用 GetCertificate 回调,中途换成新证书(CN 从 server-v1 变 server-v2)。换证书之后,已有连接上再调用:客户端累计握手 1 次,看到的证书只有 server-v1——已建立的连接继续用旧证书,不重新握手;新建一个连接后,累计握手 2 次,看到的是 server-v1 和 server-v2。所以换证书不会影响已有连接,新证书只对之后的新连接生效;要让所有连接都用上新证书,需要让连接重建(服务端 MaxConnectionAge,第 40 篇)。", t=tl(S(4)), done=lidx(S(4), '新建一个连接'), mark=lidx(S(4), '换证书之后'), b=bars([['已有连接再调用后,累计握手次数', 1, '1'], ['新建连接后,累计握手次数', 2, '2']], 3, mark=[0], done=[1]), kv=KV([['已有连接', '继续用 server-v1,不重新握手'], ['新连接', '拿到 server-v2'], ['让旧连接换证书', '要让连接重建']], ['已有连接'])),
    step("握手的代价:新建连接并完成第一次调用的中位数耗时(各 30 次,本机回环):明文 0.3 ms;TLS(ECDSA P-256 证书)0.9 ms;TLS(RSA 2048 证书)1.7 ms。TLS 握手在回环上增加了零点几到一点几毫秒,主要是证书验证和签名;在真实网络上还要加上握手需要的往返次数(本机测不出)。同一条连接上之后的调用不再付这个代价,所以连接要复用(第 38 篇)。", t=tl(S(5)), done=lidx(S(5), 'TLS RSA 2048'), mark=lidx(S(5), '明文 '), b=bars([['明文 ms', 0.3, '0.3'], ['TLS ECDSA ms', 0.9, '0.9'], ['TLS RSA 2048 ms', 1.7, '1.7']], 2, mark=[0], done=[1, 2]), kv=KV([['明文', '0.3 ms'], ['TLS ECDSA P-256', '0.9 ms'], ['TLS RSA 2048', '1.7 ms']], ['TLS ECDSA P-256'])),
]
A = mkarth('h25', 25, 'gRPC,TLS,mTLS,证书,x509,证书轮换,ALPN,握手,Go,真实验证,动画演示',
    '实测 gRPC 的 TLS/mTLS:证书各种问题时客户端看到的 Unavailable 错误文字;mTLS 缺证书、错 CA 的差别;服务端从 AuthInfo 读客户端身份;证书轮换只对新连接生效;握手的耗时。',
    '给 gRPC 加 TLS 之后,证书过期、域名不对、客户端没证书,分别会看到什么错误?已有连接会不会用上新证书?这篇用内存里生成的 CA 和证书逐项验证,所有错误文字都是真实输出。',
    [('全部 Unavailable', '证书、协议、明文/TLS 不匹配等 8 种出错场景,客户端 code 都是 Unavailable,原因在 message 里'), ('CN=client-A', 'mTLS 成功时服务端从 peer.AuthInfo 里读到的客户端证书身份'), ('server-v1 → server-v2', '证书轮换:已有连接继续看到旧证书,新连接才拿到新证书')],
    [('TLS 里的 gRPC', '<p>gRPC 用 HTTP/2,TLS 握手里通过 ALPN 协商 h2。服务端用 grpc.Creds 设置证书,客户端用 credentials 里的 TLS 设置根证书和 ServerName。</p>'),
     ('错误都是 Unavailable', '<p>握手失败时调用立即以 Unavailable 失败,具体原因(未知签发者、域名不对、过期、没有 SAN 等)写在 message 里,排查看这句话。</p>'),
     ('mTLS', '<p>服务端要求客户端证书时,缺证书或证书不被信任都会让调用失败;成功后 handler 可以从 peer 的 TLSInfo 读到客户端证书,用证书里的身份做鉴权。</p>'),
     ('证书轮换', '<p>GetCertificate 回调能在服务端不重启的情况下换证书,但已建立的连接不受影响,只有新连接用新证书。</p>'),
     ('握手成本', '<p>握手只在新建连接时付一次;回环上 ECDSA 比 RSA 2048 快。真实网络还要加握手的往返延迟。</p>')],
    steps,
    [ENV_H + '。CA 和证书都在程序里用 crypto/x509 生成(ECDSA P-256,另外一组 RSA 2048),没有写盘;错误文字是客户端调用返回的原文;“Go 的 TLS 客户端只发送签发者在服务端 CA 列表里的证书”是用“正常配置 vs 强制发送”两种发法得到的现象,解释属于推断;握手耗时是本机回环的中位数',
     '没有验证:证书吊销(CRL/OCSP);TLS 会话恢复(session resumption)对 gRPC 重连的影响;客户端系统根在 Linux/Windows 上的错误文字;ALTS、SPIFFE、xDS 的证书提供者;更换 CA 根时的双信任过渡;mTLS 在经过七层代理(如 Envoy)终止 TLS 之后的身份传递'],
    'TLS 与 mTLS')
